mapper.insert:
INSERT INTO outbox_events (
    event_id, aggregate_type, aggregate_id, event_type, schema_version, 
    partition_key, payload, delivery_status, attempt_count, next_attempt_at, occurred_at
) VALUES (
    #{eventId}, #{aggregateType}, #{aggregateId}, #{eventType}, #{schemaVersion},
    #{partitionKey}, #{payload}::jsonb, #{deliveryStatus}, #{attemptCount}, #{nextAttemptAt}, #{occurredAt}
)

mapper.select:
SELECT *
FROM outbox_events
WHERE delivery_status IN ('PENDING', 'PROCESSING')
  AND next_attempt_at <= #{now}
ORDER BY created_at ASC
LIMIT #{limit}

mapper.update:
UPDATE outbox_events
SET delivery_status = 'PUBLISHED',
    published_at = #{publishedAt}
WHERE event_id = #{eventId}
